import{_ as s,o as i,c as o,am as t}from"./chunks/framework._FJXuPhs.js";const d=JSON.parse('{"title":"分布式授权访问","description":"","frontmatter":{"title":"分布式授权访问","excerpt":"分布式授权访问","date":"2024-03-22 16:28:33","updated":"2024-03-22 16:28:33"},"headers":[],"relativePath":"架构篇/分布式系统/分布式授权访问/index.md","filePath":"架构篇/分布式系统/分布式授权访问/index.md","lastUpdated":null}'),n={name:"架构篇/分布式系统/分布式授权访问/index.md"};function a(l,e,p,r,c,h){return i(),o("div",null,[...e[0]||(e[0]=[t('<ul><li><strong>认证 (Authentication)：</strong> 你是谁。</li><li><strong>授权 (Authorization)：</strong> 你有权限干什么</li></ul><p>引入基础概念</p><ul><li>RBAC 模型 <ul><li>RBAC 即基于角色的权限访问控制（Role-Based Access Control）。这是一种通过角色关联权限，角色同时又关联用户的授权的方式</li></ul></li></ul><p>认证授权</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240322201429.png" alt="image.png"></p><h3 id="_1、cookie-的作用" tabindex="-1">1、Cookie 的作用 <a class="header-anchor" href="#_1、cookie-的作用" aria-label="Permalink to &quot;1、Cookie 的作用&quot;">​</a></h3><p>Cookie 是保存在浏览器的一个信息，Session 是保存在服务器的一个信息</p><p>使用 cookie 的登陆流程</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240322184719.png" alt="image.png"></p><h3 id="_2、分布式-session" tabindex="-1">2、分布式 session <a class="header-anchor" href="#_2、分布式-session" aria-label="Permalink to &quot;2、分布式 session&quot;">​</a></h3><p>分时式 session 会遇到的问题：</p><p>举个例子：假如我们部署了两份相同的服务 A，B，用户第一次登陆的时候 ，Nginx 通过负载均衡机制将用户请求转发到 A 服务器，此时用户的 Session 信息保存在 A 服务器。结果，用户第二次访问的时候 Nginx 将请求路由到 B 服务器，由于 B 服务器没有保存 用户的 Session 信息，导致用户需要重新进行登陆。</p><p>这里的问题就是需要将 session 能够同步到所有关联的服务器，并通过浏览器的 cookie 能够进行授权访问</p><p>常见的解决方案：</p><ol><li>某个用户的所有请求都通过特性的哈希策略分配给同一个服务器处理。这样的话，每个服务器都保存了一部分用户的 Session 信息。服务器宕机，其保存的所有 Session 信息就完全丢失了。</li><li>每一个服务器保存的 Session 信息都是互相同步的，也就是说每一个服务器都保存了全量的 Session 信息。每当一个服务器的 Session 信息发生变化，我们就将其同步到其他服务器。这种方案成本太大，并且，节点越多时，同步成本也越高。</li><li>单独使用一个所有服务器都能访问到的数据节点（比如缓存）来存放 Session 信息。为了保证高可用，数据节点尽量要避免是单点。</li><li>Spring Session 是一个用于在多个服务器之间管理会话的项目。它可以与多种后端存储（如 Redis、MongoDB 等）集成，从而实现分布式会话管理。通过 Spring Session，可以将会话数据存储在共享的外部存储中，以实现跨服务器的会话同步和共享。</li></ol><p>使用 session 进行登陆会遇到的问题：</p><p>当别人拿取到你浏览器中的 cookie 信息，可用进行非法请求访问（获取到你 cookie 中的 session ID信息），并不能禁止 CSRF 攻击。（跨站请求伪造）</p><p>而 token 一般会存放到 Local Storage 中</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240322185741.png" alt="image.png"></p><p>看了一下为啥跳转链接 cookie 会有风险，一个需要显式携带，一个是浏览器自动附带。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240322190152.png" alt="image.png"></p><h3 id="_3、jwt" tabindex="-1">3、JWT <a class="header-anchor" href="#_3、jwt" aria-label="Permalink to &quot;3、JWT&quot;">​</a></h3><p>JWT 本身也是 Token，一种规范化之后的 JSON 结构的 Token。</p><p>JWT 自身包含了身份验证所需要的所有信息，因此，我们的服务器不需要存储 Session 信息。这显然增加了系统的可用性和伸缩性，大大减轻了服务端的压力。</p><p>组成结构：头部、有效载荷、签名</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240322190335.png" alt="image.png"></p><p>JWT 本质上就是一组字串，通过（<code>.</code>）切分成三个为 Base64 编码的部分：</p><ul><li><strong>Header</strong> : 描述 JWT 的元数据，定义了生成签名的算法以及 <code>Token</code> 的类型。</li><li><strong>Payload</strong> : 用来存放实际需要传递的数据</li><li><strong>Signature（签名）</strong>：服务器通过 Payload、Header 和一个密钥(Secret)使用 Header 里面指定的签名算法（默认是 HMAC SHA256）生成。</li></ul><p>JWT 通常是这样的：<code>xxxxx.yyyyy.zzzzz</code>。</p><p>一般我们会将 token 存放到 redis 中，通过判定它过期时间以及 是否当前用户在 redis 中的 token 和 前端的 token 进行一一匹配，进行认证。</p><h3 id="_4、单点登陆-sso" tabindex="-1">4、单点登陆 SSO <a class="header-anchor" href="#_4、单点登陆-sso" aria-label="Permalink to &quot;4、单点登陆 SSO&quot;">​</a></h3><p>SSO 英文全称 Single Sign On，单点登录。SSO 是在多个应用系统中，用户只需要登录一次就可以访问所有相互信任的应用系统。</p><p>用户在浏览需要登录的页面时，客户端将 AuthToken 提交给 SSO 服务校验登录状态/获取用户登录信息</p><p>对于登录信息的存储，建议采用 Redis，使用 Redis 集群来存储登录信息，既可以保证高可用，又可以线性扩充。同时也可以让 SSO 服务满足负载均衡/可伸缩的需求。</p><p>登陆操作相关的流程图可以看一下这个： <a href="https://javaguide.cn/system-design/security/sso-intro.html#%E8%B7%A8%E5%9F%9F%E7%99%BB%E5%BD%95%E3%80%81%E7%99%BB%E5%87%BA" target="_blank" rel="noreferrer">https://javaguide.cn/system-design/security/sso-intro.html#跨域登录、登出</a></p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240322200959.png" alt="image.png"></p><h3 id="_5、oauth2" tabindex="-1">5、OAuth2 <a class="header-anchor" href="#_5、oauth2" aria-label="Permalink to &quot;5、OAuth2&quot;">​</a></h3><p>OAuth 2.0是一个开放标准的授权协议，允许第三方应用获得有限的访问权限，以代表资源所有者（如用户）访问其在资源服务器上的资源，而无需将用户名和密码直接暴露给第三方应用。</p><p>【第三方授权】</p><ul><li><a href="/java-site/架构篇/分布式系统/分布式授权访问/OAuth 方式进行授权.html">OAuth 方式进行授权</a></li></ul><p>参考</p><ul><li><a href="https://javaguide.cn/system-design/security/basis-of-authority-certification.html" target="_blank" rel="noreferrer">https://javaguide.cn/system-design/security/basis-of-authority-certification.html</a></li></ul>',42)])])}const g=s(n,[["render",a]]);export{d as __pageData,g as default};
